// The profile facts: writes web/src/facts.js (what the phones show in animal profiles, trait notes and egg cards) from the one store of
// checked facts, server/discovery/facts.json. Edit the store, never the generated file.
//
// What is shown: a verified record always; a rejected or held one never. A record that is not yet verified is shown only while the store's
// meta.transition is on, and only if it was already in the game before the audit and the audit kept or corrected it (so the profiles do not
// go empty while the source pages cannot be fetched). Turn transition off (or run with --strict) and only verified facts are shown.
//   node tools/facts_build.mjs [--strict]
import fs from 'node:fs';
import { checkFacts } from '../server/discovery/validate.mjs';
const store = JSON.parse(fs.readFileSync('server/discovery/facts.json', 'utf8')), bank = JSON.parse(fs.readFileSync('server/discovery/bank.json', 'utf8'));
const strict = process.argv.includes('--strict') || !store.meta?.transition, chk = checkFacts(store.facts, bank), bad = new Set(chk.entries.filter((x) => x.errors.length).map((x) => x.id));
const shown = (r) => r.status === 'verified' ? !bad.has(r.id) : !strict && r.legacy && ['keep', 'fix'].includes(r.prereview?.verdict) && r.status === 'unverified' && !bad.has(r.id);
const FACTS = {}, TRAIT_FACTS = {}, EGG_FACTS = {}; let n = 0;
for (const r of store.facts) { if (!shown(r)) continue; n++;
  for (const sp of r.species) {
    if (r.kind === 'profile') (FACTS[sp] ||= []).push(r.text);
    if (r.kind === 'trait') ((TRAIT_FACTS[sp] ||= {})[r.trait] = r.real ? `${r.game} ${r.real}` : r.game);
    if (r.kind === 'eggcare') EGG_FACTS[sp] = r.text;
  } }
const js = `// GENERATED by tools/facts_build.mjs from server/discovery/facts.json (the one store of checked facts). Do not edit by hand.
// ${n} of ${store.facts.length} facts shown${strict ? ' (verified only)' : ' (verified, plus audited facts from before the audit while their sources wait to be fetched)'}.
export const FACTS = ${JSON.stringify(FACTS, null, 1)};
const dayN = () => Math.floor(Date.now() / 864e5);
export function factOfDay(species, extra = 0) { const L = FACTS[species] ?? []; if (!L.length) return null; return { text: L[(dayN() + extra) % L.length], n: ((dayN() + extra) % L.length) + 1, of: L.length }; }
// how a trait shows up: the game's part, then (where it can be sourced) the real animal's
export const TRAIT_FACTS = ${JSON.stringify(TRAIT_FACTS, null, 1)};
// how each kind really looks after its eggs (the egg card)
export const EGG_FACTS = ${JSON.stringify(EGG_FACTS, null, 1)};
`;
fs.writeFileSync('web/src/facts.js', js);
console.log(`facts.js: ${n} shown of ${store.facts.length} (${strict ? 'strict' : 'transition'}); records with errors: ${bad.size}; store errors: ${chk.bankErrors.length}`); for (const e of chk.bankErrors) console.log('  ', e);
